PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance (AVG(?avgShortfallInv) AS ?avg_goal_shortfall) (AVG(?avgRiskScoreInv) AS ?avg_portfolio_health_score)
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:riskTolerance ?riskTolRaw . }
  BIND(COALESCE(STR(?riskTolRaw), "NULL") AS ?riskTolerance)

  {
    SELECT ?investorId (AVG(xsd:decimal(?shortfall)) AS ?avgShortfallInv)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScoreInv)
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:investorId ?investorId ;
          wm:riskScore ?riskScore .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance (AVG(xsd:decimal(?invAvgProgress)) AS ?avg_goal_progress) (AVG(xsd:decimal(?invRiskScore)) AS ?avg_portfolio_risk)
WHERE {
  {
    SELECT ?inv (AVG(xsd:decimal(?progress)) AS ?invAvgProgress)
    WHERE {
      ?inv a wm:Investor .
      ?inv wm:hasInvestmentGoal ?goal .
      ?goal wm:progressPct ?progress .
    }
    GROUP BY ?inv
  }
  {
    SELECT ?inv (AVG(xsd:decimal(?riskScore)) AS ?invRiskScore)
    WHERE {
      ?inv a wm:Investor .
      ?inv wm:hasPortfolioHealth ?ph .
      ?ph wm:riskScore ?riskScore .
    }
    GROUP BY ?inv
  }
  OPTIONAL { ?inv wm:riskTolerance ?rtRaw . }
  BIND(COALESCE(STR(?rtRaw), "NULL") AS ?riskTolerance)
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investment_type
       (AVG(xsd:decimal(?riskScore)) AS ?avg_risk_score)
       (AVG(xsd:decimal(?diversificationScore)) AS ?avg_diversification_score)
       (AVG(xsd:decimal(?liquidityScore)) AS ?avg_liquidity_score)
WHERE {
  {
    SELECT DISTINCT ?investmentType ?investor WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:hasInvestmentType ?investmentType ;
               wm:heldByInvestor ?investor .
    }
  }
  ?investmentType a wm:InvestmentType ;
                  rdfs:label ?investment_type .
  ?health a wm:PortfolioHealth ;
          wm:healthOfInvestor ?investor ;
          wm:riskScore ?riskScore ;
          wm:diversificationScore ?diversificationScore ;
          wm:liquidityScore ?liquidityScore .
}
GROUP BY ?investment_type

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?goal_context (AVG(xsd:decimal(?progressPct)) AS ?average_progress)
WHERE {
  ?goal a wm:InvestmentGoal ;
        wm:description ?goal_context ;
        wm:progressPct ?progressPct ;
        wm:belongsToInvestor ?inv .
  ?inv a wm:Investor ;
       wm:riskTolerance ?riskTol .
  FILTER(LCASE(STR(?riskTol)) = "aggressive")
}
GROUP BY ?goal_context
ORDER BY DESC(?average_progress) ?goal_context
LIMIT 5

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investment_type (COUNT(DISTINCT ?holdingId) AS ?holding_count)
WHERE {
  ?holding rdf:type wm:PortfolioHolding ;
           wm:hasInvestmentType ?invType ;
           wm:holdingId ?holdingId .
  ?invType rdf:type wm:InvestmentType ;
           rdfs:label ?investment_type .
}
GROUP BY ?investment_type
